-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial misstatement threshold application
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Peak Industries, the auditor set overall materiality at $200,000 and performance materiality at $150,000. The team established a threshold of $4,000 for clearly trivial misstatements. A $3,500 pricing error is found in inventory. Under AU-C 450, how should the auditor treat this misstatement?', '["The auditor need not accumulate this misstatement because it is below the clearly trivial threshold", "The auditor must accumulate the misstatement and include it in the summary of uncorrected misstatements", "The auditor must communicate this misstatement to those charged with governance", "The auditor must request management to correct this misstatement before issuing the report"]'::jsonb, 0, 'Under AU-C 450.05, the auditor accumulates misstatements identified during the audit other than those that are clearly trivial. Because the $3,500 error falls below the $4,000 clearly trivial threshold, the auditor need not accumulate it. While choice B suggests accumulating all misstatements regardless of size, AU-C 450 explicitly permits excluding amounts that are clearly trivial — meaning amounts so small they would not be material individually or in aggregate.', 'medium', 2),

-- Q2: easy / L1 — Definition of tolerable misstatement
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 530, what is the definition of tolerable misstatement in an audit sampling context?', '["The maximum aggregate misstatement permitted in the financial statements taken as a whole", "The application of performance materiality to a particular sampling procedure", "The threshold below which all misstatements are considered clearly trivial", "The amount of detected misstatement that triggers a qualified opinion"]'::jsonb, 1, 'Under AU-C 530.05, tolerable misstatement is the application of performance materiality to a particular sampling procedure. It represents the maximum misstatement in a population that the auditor is willing to accept for a specific test. Choice A describes overall materiality rather than tolerable misstatement, which operates at the individual test level and is set at or below performance materiality.', 'easy', 1),

-- Q3: easy / L1 — Three categories of misstatements under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, which three categories describe the nature of misstatements identified during an audit?', '["Material, immaterial, and clearly trivial", "Intentional, unintentional, and systemic", "Factual, judgmental, and projected", "Known, likely, and estimated"]'::jsonb, 2, 'Under AU-C 450.A1-A3, misstatements are categorized as factual (misstatements about which there is no doubt), judgmental (differences arising from management''s judgments about estimates or accounting policies the auditor considers unreasonable), and projected (the auditor''s best estimate of misstatements in populations extrapolated from sample results). Unlike the AU-C 450 framework, choice B confuses the nature of misstatements with the intent behind errors.', 'easy', 1),

-- Q4: medium / L2 — Prior-year uncorrected misstatements affecting current period
(1, 'Misstatements and Control Deficiencies', 'Redstone Logistics had $35,000 in uncorrected misstatements from the prior-year audit, including a $22,000 understatement of accrued liabilities that reversed in the current period. Current materiality is $100,000. When evaluating current-year misstatements, the auditor should:', '["Ignore prior-year misstatements because they were evaluated in the prior audit", "Evaluate only the net effect of prior-year reversals on current-year income", "Evaluate only current-year misstatements since management accepted the prior-year risk", "Consider the effect of prior-year uncorrected misstatements on current-year financial statements"]'::jsonb, 3, 'Under AU-C 450.06, the auditor must determine whether uncorrected misstatements from prior periods affect the current-period financial statements. The $22,000 reversal shifts income between periods, potentially overstating current-year income. However, choice B is too narrow because the auditor must consider the full impact on all affected line items, not just the income statement net effect.', 'medium', 2),

-- Q5: hard / L4 — Immaterial intentional misstatement as potential fraud indicator
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Holdings, the engagement team discovers that the CFO intentionally reclassified $18,000 of operating expenses as capital expenditures to improve the operating income margin. Overall materiality is $500,000 and the amount is quantitatively immaterial. The auditor should evaluate whether this misstatement:', '["Indicates a risk of material misstatement due to fraud that requires reconsidering the audit strategy", "Can be waived since it is below both materiality and performance materiality", "Should be treated identically to an unintentional misstatement of the same amount", "Requires automatic withdrawal from the engagement under professional standards"]'::jsonb, 0, 'Under AU-C 450.A4 and AU-C 240, an intentional misstatement — even if quantitatively immaterial — may indicate a risk of material misstatement due to fraud. The auditor must evaluate the implications for the integrity of management and the overall audit strategy. Although choice C equates intentional and unintentional misstatements, AU-C 240.35 requires heightened skepticism because intentional manipulation raises concerns about management honesty regardless of dollar amount.', 'hard', 4),

-- Q6: hard / L4 — IT general control deficiency affecting multiple business processes
(1, 'Misstatements and Control Deficiencies', 'Meridian Financial Group relies on an ERP system for revenue recognition, accounts payable, and payroll processing. During the audit, the team discovers that the system administrator has unrestricted access to modify transaction data without logging, and no independent review of changes occurs. The auditor should evaluate this IT general control deficiency by:', '["Limiting the assessment to the single business process with the highest transaction volume", "Considering the potential magnitude across all business processes affected by the deficiency and the likelihood of misstatement in each", "Classifying the deficiency as a significant deficiency because IT controls are not direct financial controls", "Reporting the deficiency to management but excluding it from the evaluation of internal control over financial reporting"]'::jsonb, 1, 'Under AU-C 265.A7 and A13, a deficiency in IT general controls can affect multiple transaction classes and business processes. The auditor must evaluate the potential for misstatement across all affected areas, considering both magnitude and likelihood in each process. Choice C incorrectly limits the classification; an ITGC deficiency affecting multiple high-volume processes could constitute a material weakness rather than merely a significant deficiency.', 'hard', 4),

-- Q7: hard / L4 — PCAOB integrated audit material weakness indicators
(1, 'Misstatements and Control Deficiencies', 'Sterling Pharmaceuticals, a publicly traded company, undergoes an integrated audit. The auditor identifies that the revenue recognition process lacks a review control for non-standard contract terms, resulting in a $175,000 misstatement in a $12 million revenue balance. Performance materiality is $300,000. The contract review process handles $8 million in complex arrangements annually. Under PCAOB AS 2201, the auditor should:', '["Classify this as a deficiency because the actual misstatement is below performance materiality", "Report this as a significant deficiency because it involves a non-routine process", "Evaluate whether there is a reasonable possibility that a material misstatement could occur given the $8 million of transactions processed through the deficient control", "Defer classification until the next audit cycle to assess whether the deficiency recurs"]'::jsonb, 2, 'Under PCAOB AS 2201.62-65, the auditor evaluates the severity of a control deficiency based on the magnitude of the potential misstatement that could result, not just the actual detected amount. Since the deficient control processes $8 million annually and already produced a $175,000 error, there is a reasonable possibility of material misstatement. Choice A incorrectly focuses on actual rather than potential misstatement, which is the correct basis for severity evaluation under AS 2201.', 'hard', 4),

-- Q8: hard / L3 — Effect of aggregate uncorrected misstatements exceeding materiality on opinion
(1, 'Misstatements and Control Deficiencies', 'During the audit of Crestline Energy Partners, the auditor accumulates $280,000 in uncorrected misstatements. Overall materiality is $250,000. Management declines to adjust because they believe the misstatements are immaterial. The misstatements affect revenue, cost of goods sold, and accounts receivable but do not render any single financial statement fundamentally unreliable. Under AU-C 705, the most likely effect on the audit opinion is:', '["An unmodified opinion with an emphasis-of-matter paragraph", "An adverse opinion because misstatements exceed materiality", "A disclaimer of opinion due to scope limitation", "A qualified opinion because the misstatements are material but not pervasive"]'::jsonb, 3, 'Under AU-C 705.08, when uncorrected misstatements are material but not pervasive to the financial statements, the auditor issues a qualified opinion. Because the $280,000 exceeds the $250,000 materiality but the misstatements do not render the statements fundamentally unreliable as a whole, a qualified rather than adverse opinion is appropriate. However, choice B would apply only if the misstatements were both material and pervasive, which the facts do not support.', 'hard', 3),

-- Q9: medium / L3 — Systematic pattern of misstatements vs isolated errors
(1, 'Misstatements and Control Deficiencies', 'During testing of Birchwood Manufacturing''s inventory system, the auditor discovers that 12 of 40 sampled items have consistent overstatements averaging 3% of recorded value. The errors all trace to the same automated pricing formula. The auditor should analyze this pattern as most likely indicating:', '["Random sampling error requiring no additional procedures", "An isolated clerical mistake affecting only the sampled items", "A bias in management''s estimates requiring additional skepticism", "A systematic error suggesting the misstatement affects the entire population priced by that formula"]'::jsonb, 3, 'Under AU-C 450.A3, when misstatements follow a pattern traceable to a single cause — here an automated pricing formula — the auditor should treat the error as systematic rather than random. A systematic error implies the entire population processed through that formula is likely affected, requiring the auditor to project the misstatement accordingly. Choice C is incorrect because the error stems from a formula defect, not management bias in estimates.', 'medium', 3),

-- Q10: easy / L1 — Auditor documentation of identified misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what must the auditor document regarding misstatements identified during the audit?', '["All misstatements accumulated during the audit and whether they have been corrected", "Only misstatements that exceed performance materiality", "Only misstatements that management has refused to correct", "All misstatements communicated to those charged with governance"]'::jsonb, 0, 'Under AU-C 450.12, the auditor must document all misstatements accumulated during the audit and whether they have been corrected. This includes both corrected and uncorrected misstatements above the clearly trivial threshold. However, choice C is too narrow because documentation requirements cover all accumulated misstatements, not only those management refuses to correct.', 'easy', 1),

-- Q11: medium / L2 — Requesting management to correct identified misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinnacle Supply Co., the auditor identifies $62,000 in misstatements from inventory count errors and $18,000 from an unrecorded vendor invoice. Performance materiality is $75,000. Under AU-C 450, the auditor''s appropriate next step regarding these misstatements is to:', '["Immediately modify the audit opinion because aggregate misstatements equal performance materiality", "Request that management correct all identified misstatements and reassess if management declines", "Waive the misstatements because neither individually exceeds performance materiality", "Communicate only the $62,000 inventory error to those charged with governance"]'::jsonb, 1, 'Under AU-C 450.07, the auditor should communicate all accumulated misstatements to the appropriate level of management and request correction. If management declines, the auditor evaluates the uncorrected misstatements individually and in aggregate. However, choice A is premature because the auditor must first give management the opportunity to make corrections before considering any opinion implications.', 'medium', 2),

-- Q12: hard / L4 — Qualitative factors making quantitatively immaterial misstatement significant
(1, 'Misstatements and Control Deficiencies', 'Northfield Bancorp reports net income of $4.2 million, and overall materiality is set at $210,000. The auditor discovers a $45,000 misstatement involving the understatement of loan loss provisions that, if corrected, would cause the bank to breach a regulatory capital ratio covenant. Management argues the amount is immaterial. The auditor should evaluate whether:', '["The misstatement can be excluded from the summary because it is clearly trivial", "The misstatement should be projected to the population to determine the full impact", "Management''s representation that the amount is immaterial provides sufficient basis to waive it", "The qualitative significance of the misstatement — including the covenant breach — overrides its quantitative immateriality"]'::jsonb, 3, 'Under AU-C 450.A6, the auditor must consider qualitative factors when evaluating misstatements, including the effect on compliance with regulatory requirements, loan covenants, and contractual obligations. A $45,000 misstatement that triggers a covenant breach has significance far beyond its dollar amount. While choice B addresses population projection, that technique is relevant for sampling extrapolation and does not address the qualitative regulatory concern here.', 'hard', 4),

-- Q13: medium / L3 — Nature versus magnitude of misstatement in evaluating significance
(1, 'Misstatements and Control Deficiencies', 'Lakewood Aerospace has two uncorrected misstatements: a $90,000 overstatement in depreciation expense caused by a computational error, and a $30,000 overstatement in executive compensation disclosures that understates related-party transactions. Materiality is $200,000. The auditor should analyze these misstatements by:', '["Combining both amounts and concluding the $120,000 aggregate is immaterial", "Focusing solely on the larger $90,000 depreciation error as the primary concern", "Evaluating each misstatement''s nature separately, recognizing the disclosure misstatement may be qualitatively significant despite its smaller dollar amount", "Requesting management correct only the depreciation error since it is the larger amount"]'::jsonb, 2, 'Under AU-C 450.11 and .A6, the auditor evaluates misstatements considering both quantitative magnitude and qualitative nature. The $30,000 related-party disclosure misstatement may be qualitatively significant because users rely on related-party disclosures for decision-making, regardless of its smaller dollar amount. Although choice A relies solely on aggregate quantitative comparison to materiality, it ignores the qualitative significance of disclosure misstatements.', 'medium', 3),

-- Q14: medium / L3 — Evaluating a disclosure omission as misstatement
(1, 'Misstatements and Control Deficiencies', 'Silverstone Manufacturing omits a contingent liability disclosure for a pending $3.2 million product liability lawsuit. Management asserts the outcome is only reasonably possible. The auditor''s independent assessment, supported by legal counsel, indicates the loss is probable and estimable at $2.8 million. Materiality is $400,000. The auditor should analyze this disclosure omission by:', '["Accepting management''s assessment because estimating litigation outcomes requires judgment", "Treating the omission as immaterial because disclosure misstatements do not affect account balances", "Evaluating the omission as a potential material misstatement because the auditor''s assessment differs from management''s and the amount exceeds materiality", "Communicating the disagreement to legal counsel and deferring to their final determination"]'::jsonb, 2, 'Under AU-C 450.A5, misstatements include qualitative disclosure omissions and misrepresentations. When the auditor''s judgment about a contingent liability''s classification differs materially from management''s, the difference constitutes a judgmental misstatement. Because $2.8 million far exceeds the $400,000 materiality, the unrecorded liability and missing disclosure represent a likely material misstatement. While choice A defers entirely to management, the auditor must exercise independent judgment on matters of this significance.', 'medium', 3),

-- Q15: easy / L1 — Management representation letter regarding uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 580, what must the auditor obtain from management regarding uncorrected misstatements?', '["A verbal acknowledgment that uncorrected misstatements exist", "A corrective action plan with specific timelines for adjustment", "An independent assessment from the audit committee confirming immateriality", "A written representation that management believes the effects of uncorrected misstatements are immaterial to the financial statements"]'::jsonb, 3, 'Under AU-C 580.A6 and AU-C 450.08, the auditor obtains written representations from management that the effects of uncorrected misstatements, individually and in aggregate, are immaterial to the financial statements as a whole. Unlike choice A, which suggests verbal acknowledgment, AU-C 580 explicitly requires written representations from management regarding uncorrected misstatements.', 'easy', 1),

-- Q16: medium / L3 — Turnover in accounting personnel as control deficiency
(1, 'Misstatements and Control Deficiencies', 'Atlas Consulting Group has experienced turnover of three controllers in the past 18 months. Each transition resulted in delayed reconciliations and inconsistent application of the revenue recognition policy. While no material misstatements were detected, the auditor should analyze this situation as most likely indicating:', '["A control environment deficiency that could have a pervasive effect on the financial statements", "A business risk that is outside the scope of the auditor''s internal control evaluation", "A staffing issue that only affects operational efficiency, not financial reporting reliability", "An inherent limitation of internal control that requires no auditor action"]'::jsonb, 0, 'Under AU-C 265.A1 and AU-C 315.14, the control environment — including management''s commitment to competence and human resource policies — is foundational to effective internal control. Repeated controller turnover causing reconciliation delays and inconsistent policies indicates a control environment deficiency that could pervasively affect financial reporting. While choice B excludes this from internal control evaluation, COSO treats the control environment as a direct component of internal control over financial reporting.', 'medium', 3),

-- Q17: easy / L1 — Timing of written communication of control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, when must the auditor communicate significant deficiencies and material weaknesses in writing to those charged with governance?', '["Within 5 business days of identification", "No later than 60 days following the report release date", "Within 30 days of the engagement letter date", "Immediately upon identification of a material weakness"]'::jsonb, 1, 'Under AU-C 265.11, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. This timeline allows the auditor to complete the evaluation of all identified deficiencies before issuing the written communication. Choice D is incorrect because, while timely communication is encouraged, the standard does not require immediate written communication upon identification.', 'easy', 1),

-- Q18: hard / L4 — Recurring material weakness from prior year still unresolved
(1, 'Misstatements and Control Deficiencies', 'Cascade Valley Healthcare received a material weakness communication regarding its revenue recognition controls in the prior year. During the current-year audit, the auditor observes that management implemented a new review procedure but discovers three revenue misstatements totaling $195,000 that originated from the same control gap. Current materiality is $300,000. The auditor should evaluate whether:', '["The new review procedure eliminates the material weakness regardless of the current-year misstatements", "The three misstatements should be excluded from evaluation because they individually fall below materiality", "The prior-year communication satisfies the reporting requirement and need not be repeated", "The material weakness persists because the remediation was ineffective at preventing misstatements from the same control gap"]'::jsonb, 3, 'Under AU-C 265.A14, the auditor must reassess the severity of previously communicated deficiencies each year. When the same control gap continues to produce misstatements despite attempted remediation, the auditor should conclude the material weakness persists. The existence of a new procedure does not automatically resolve the deficiency if it fails to prevent the same type of errors. Choice C is incorrect because AU-C 265.12 requires re-communication of material weaknesses that remain unremediated.', 'hard', 4),

-- Q19: medium / L2 — Pervasive misstatement warranting adverse opinion
(1, 'Misstatements and Control Deficiencies', 'Harborview Enterprises has $420,000 in uncorrected misstatements affecting revenue, inventory, accounts receivable, and retained earnings. Overall materiality is $350,000. The misstatements collectively distort the relationships between multiple financial statement elements. Under AU-C 705, the auditor should determine whether:', '["A qualified opinion is appropriate because the misstatements exceed materiality", "An unmodified opinion with an other-matter paragraph is sufficient disclosure", "An adverse opinion is warranted because the misstatements are both material and pervasive to the financial statements", "A disclaimer of opinion is required due to the scope of the misstatements"]'::jsonb, 2, 'Under AU-C 705.09, when uncorrected misstatements are both material and pervasive — meaning they affect multiple elements, accounts, or disclosures and distort the overall presentation — the auditor issues an adverse opinion. The $420,000 exceeding materiality across revenue, inventory, receivables, and retained earnings meets the pervasiveness criterion. Choice A would apply only if the misstatements were material but confined to specific elements rather than pervasive.', 'medium', 2),

-- Q20: medium / L2 — Misstatement from inappropriate accounting policy selection
(1, 'Misstatements and Control Deficiencies', 'Thornton Medical Devices recognizes revenue for its bundled software-hardware contracts at the point of hardware delivery, without allocating the transaction price to the software support obligation. The auditor determines this policy does not comply with ASC 606, resulting in a $275,000 overstatement of current-year revenue. Materiality is $200,000. Under AU-C 450, this misstatement is best classified as:', '["A projected misstatement because it must be extrapolated to similar contracts", "A clearly trivial amount that need not be accumulated", "A factual misstatement because it involves a computational error", "A judgmental misstatement arising from an inappropriate accounting policy selection"]'::jsonb, 3, 'Under AU-C 450.A2, judgmental misstatements include differences arising from management''s selection of accounting policies the auditor considers inappropriate. The failure to allocate transaction price under ASC 606 reflects a policy choice, not a calculation error or sampling extrapolation. Choice C incorrectly classifies this as factual; factual misstatements involve verifiable errors, whereas policy disagreements are judgmental in nature.', 'medium', 2),

-- Q21: easy / L1 — Basic definition of control deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what constitutes a deficiency in internal control over financial reporting?', '["Any error identified during substantive testing of account balances", "A material misstatement in the prior-year financial statements", "An auditor''s inability to obtain sufficient appropriate audit evidence", "A condition where a control''s design or operation does not allow management or employees to prevent or detect misstatements on a timely basis"]'::jsonb, 3, 'Under AU-C 265.06, a deficiency in internal control exists when the design or operation of a control does not allow management or employees, in the normal course of performing their functions, to prevent or detect and correct misstatements on a timely basis. Unlike choice A, which confuses substantive testing results with control evaluation, a deficiency relates specifically to the design or operational effectiveness of controls.', 'easy', 1),

-- Q22: easy / L1 — Entity-level controls concept
(1, 'Misstatements and Control Deficiencies', 'Which of the following best describes entity-level controls in the context of evaluating control deficiencies?', '["Controls that operate at the organizational level and have a pervasive effect on the entity''s system of internal control", "Controls that apply only to a single transaction class or account balance", "Manual reconciliations performed by individual department managers", "Automated input validation checks within a specific application module"]'::jsonb, 0, 'Under AU-C 315.A77-A79, entity-level controls operate at the organizational level and include elements such as the control environment, risk assessment process, and monitoring activities. These controls have a pervasive effect on the entity''s internal control system and can affect the evaluation of other control deficiencies. In contrast, choice B describes transaction-level controls, which operate at the individual process level rather than across the organization.', 'easy', 1),

-- Q23: easy / L2 — Identifying a misstatement related to an accounting estimate
(1, 'Misstatements and Control Deficiencies', 'Bridgeport Financial Services records a $140,000 allowance for loan losses based on management''s estimate of historical default rates. The auditor''s independent analysis, using the same data but different economic assumptions, produces a range of $180,000 to $220,000. Under AU-C 540, this difference is best identified as:', '["A factual misstatement because the recorded amount is verifiably wrong", "A judgmental misstatement arising from a difference in the auditor''s and management''s estimates", "A projected misstatement based on audit sampling results", "An immaterial variance requiring no further action"]'::jsonb, 1, 'Under AU-C 540.18 and AU-C 450.A2, when the auditor''s point estimate or range differs from management''s recorded amount due to differing assumptions or judgments, the difference is a judgmental misstatement. The auditor must evaluate whether the $40,000 to $80,000 difference is material. Choice A is incorrect because the misstatement involves professional judgment about assumptions rather than a verifiable factual error.', 'easy', 2),

-- Q24: medium / L2 — Restatement as indicator of material weakness
(1, 'Misstatements and Control Deficiencies', 'Evergreen Hospitality Group restates its prior-year financial statements to correct a $380,000 revenue recognition error that was not detected during the prior-year audit. Current-year materiality is $250,000. Under AU-C 265, the auditor should evaluate the restatement as:', '["A current-year misstatement to include in the summary of uncorrected differences", "An indicator of a management integrity issue that requires withdrawal from the engagement", "An indicator of a material weakness in internal control because the entity''s controls failed to prevent or detect the material misstatement", "A prior-period event that has no bearing on the current-year control deficiency evaluation"]'::jsonb, 2, 'Under AU-C 265.A5, a restatement of previously issued financial statements to correct a material misstatement is a strong indicator of a material weakness in internal control. The entity''s controls failed to prevent or detect the $380,000 error, which exceeded materiality. Choice D is incorrect because a restatement directly informs the current-year evaluation of control effectiveness — a system that allowed a material misstatement to go undetected has a deficiency that persists until remediated.', 'medium', 2),

-- Q25: medium / L3 — Concentration of misstatements in one financial statement area
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Rim Trading Co., the auditor accumulates seven uncorrected misstatements totaling $85,000. Overall materiality is $150,000. Five of the seven misstatements, totaling $72,000, relate to accounts receivable valuation. The auditor should analyze the concentration by:', '["Dismissing the pattern because the aggregate is below both materiality and performance materiality", "Expanding substantive testing across all financial statement areas to search for additional misstatements", "Considering whether the concentration in accounts receivable indicates a higher risk of material misstatement in that area, potentially warranting additional procedures", "Issuing a qualified opinion on accounts receivable specifically"]'::jsonb, 2, 'Under AU-C 450.11 and .A11, when evaluating uncorrected misstatements, the auditor considers whether they indicate a pattern or concentration in a particular area. A concentration of $72,000 in receivables suggests a higher risk of material misstatement and may warrant additional audit procedures in that area. However, choice A ignores the concentration signal and the need to reassess risk at the account level even when the aggregate is below overall materiality.', 'medium', 3),

-- Q26: medium / L3 — Known misstatement vs projected misstatement in evaluation
(1, 'Misstatements and Control Deficiencies', 'Ridgeway Electronics'' auditor finds three confirmed pricing errors totaling $48,000 and projects an additional $95,000 in likely misstatement based on sample extrapolation. Performance materiality is $120,000 and overall materiality is $160,000. The auditor should analyze the total expected misstatement by:', '["Combining the $48,000 known misstatement with the $95,000 projected misstatement for a total expected misstatement of $143,000, which exceeds performance materiality", "Evaluating only the $48,000 known misstatement because projected amounts are speculative", "Ignoring both amounts because neither individually exceeds materiality", "Reducing the projected misstatement by the known amount to avoid double-counting"]'::jsonb, 0, 'Under AU-C 450.06 and .A9, the auditor combines known misstatements with projected misstatements to assess the total likely misstatement. The $143,000 combined total exceeds performance materiality of $120,000, requiring the auditor to consider additional procedures or request corrections. Although choice B disregards projected misstatements, they are a critical component of the auditor''s evaluation under sampling standards and cannot be ignored.', 'medium', 3),

-- Q27: easy / L1 — Purpose of accumulating audit misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of accumulating identified misstatements during an audit?', '["To document the total hours spent on substantive testing procedures", "To evaluate whether uncorrected misstatements, individually or in aggregate, are material to the financial statements", "To calculate the exact adjusting entries management must record", "To determine the fee for the audit engagement based on error volume"]'::jsonb, 1, 'Under AU-C 450.10, the primary purpose of accumulating misstatements is to enable the auditor to evaluate whether uncorrected misstatements, individually or in aggregate, are material to the financial statements as a whole. This evaluation directly affects the audit opinion. Choice C is incorrect because while the auditor requests corrections, the accumulation''s primary purpose is evaluating materiality impact, not prescribing specific journal entries.', 'easy', 1),

-- Q28: medium / L2 — Segregation of duties deficiency classification
(1, 'Misstatements and Control Deficiencies', 'Copperfield Retail Corp. employs a single bookkeeper who records cash receipts, prepares bank deposits, and reconciles the bank statement monthly. Annual cash receipts total $6.5 million. The auditor set materiality at $325,000. Under AU-C 265, the auditor should classify this segregation of duties deficiency as:', '["A deficiency that does not require communication because it involves routine transactions", "A significant deficiency because the bookkeeper appears competent and trustworthy", "At least a significant deficiency, and likely a material weakness, because the lack of segregation over $6.5 million in cash receipts creates a reasonable possibility of material misstatement", "An operational matter outside the scope of the financial statement audit"]'::jsonb, 2, 'Under AU-C 265.A12, a lack of segregation of duties over significant asset classes is an indicator of at least a significant deficiency. When one person controls recording, custody, and reconciliation of $6.5 million in cash — far exceeding materiality — there is a reasonable possibility that a material misstatement could occur and not be detected, meeting the definition of a material weakness. While choice B relies on perceived trustworthiness, personal attributes cannot mitigate a structural control weakness under auditing standards.', 'medium', 2),

-- Q29: medium / L3 — Directional consistency of misstatements suggesting management bias
(1, 'Misstatements and Control Deficiencies', 'Westbrook Properties'' auditor identifies 15 individually immaterial uncorrected misstatements from various accounts. Eight overstate assets while seven understate liabilities, all in the same direction of overstating net income. The aggregate net effect is $110,000 against materiality of $150,000. The auditor should analyze this pattern by:', '["Concluding the misstatements are immaterial because the aggregate is below materiality", "Considering whether the directional consistency suggests a possible management bias that warrants further investigation", "Netting the asset overstatements against the liability understatements to reduce the aggregate impact", "Excluding the liability misstatements because they were individually clearly trivial"]'::jsonb, 1, 'Under AU-C 450.A7, the auditor should consider whether uncorrected misstatements have a common directional pattern that could indicate management bias. When 15 misstatements across different accounts all overstate net income, the directional consistency is a red flag even if the aggregate remains below materiality. Although choice A focuses on the quantitative aggregate, AU-C 450.11 requires the auditor to separately evaluate qualitative signals of potential bias regardless of the dollar amount.', 'medium', 3),

-- Q30: medium / L2 — Restricted use of control deficiency communication
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Foxworth Engineering LLC, the auditor prepares the written communication of significant deficiencies and material weaknesses. The client''s bank requests a copy of the communication. Under AU-C 265, the auditor should:', '["Include a statement in the communication that it is intended solely for those charged with governance and management and is not intended for anyone else", "Provide the bank with the communication because lenders have a legitimate interest in internal control", "Issue a separate, expanded report for the bank that includes all identified deficiencies", "Decline to issue any written communication if third parties may request access"]'::jsonb, 0, 'Under AU-C 265.13, the written communication of significant deficiencies and material weaknesses must include a statement that it is intended solely for the information and use of those charged with governance, management, and others within the organization, and is not intended for anyone else. Choice B is incorrect because AU-C 265 restricts the intended users of this communication, and providing it to the bank without appropriate context would be improper.', 'medium', 2)
;

COMMIT;
